-- Generated localized release notes.
local _, namespace = ...
namespace.releaseNotesByLocale = {["deDE"]={["sections"]={{["illustration"]="quest-partners",["items"]={"Dein QuestTogether-Minimap-Button pulsiert jetzt mit demselben goldenen Logo-Leuchten wie Spielernamensplaketten, während „Suche nach Questpartnern“ aktiviert ist.","Das Leuchten folgt deinem Partnerstatus und endet, wenn QT deaktiviert ist oder der Minimap-Button ausgeblendet wird. Dein Button und dein Logo behalten ihre bestehende Größe."},["title"]="Eine leuchtende Minikarten-Erinnerung"}},["version"]="5.16.5",["welcome"]="Sieh auf einen Blick, wann du nach Questpartnern suchst."},["esES"]={["sections"]={{["illustration"]="quest-partners",["items"]={"El botón de QuestTogether del minimapa ahora palpita con el mismo brillo dorado del logotipo que las placas de nombre de los jugadores mientras Buscar compañeros para hacer misiones está activado.","El brillo sigue tu estado de compañero y se detiene cuando QT está desactivado o el botón del minimapa está oculto. Tu botón y el logotipo mantienen su tamaño actual."},["title"]="Un recordatorio luminoso en el minimapa"}},["version"]="5.16.5",["welcome"]="Consulta de un vistazo cuándo estás buscando compañeros para hacer misiones."},["esMX"]={["sections"]={{["illustration"]="quest-partners",["items"]={"Tu botón de QuestTogether en el minimapa ahora pulsa con el mismo brillo dorado del logo que las placas de nombre de los jugadores mientras Buscar compañeros para misiones está activado.","El brillo sigue tu estado de compañero y se detiene cuando QT está desactivado o el botón del minimapa está oculto. Tu botón y el logo mantienen su tamaño actual."},["title"]="Un recordatorio brillante en el minimapa"}},["version"]="5.16.5",["welcome"]="Ve de un vistazo cuando estés buscando compañeros para misiones."},["frFR"]={["sections"]={{["illustration"]="quest-partners",["items"]={"Le bouton QuestTogether de votre minicarte clignote désormais avec la même lueur dorée du logo que les barres d’info des personnages-joueurs tant que Recherche de partenaires de quête est activée.","La lueur suit votre statut de partenaire et s’arrête quand QT est désactivé ou quand le bouton de la minicarte est masqué. Votre bouton et le logo conservent leur taille actuelle."},["title"]="Un rappel lumineux sur la minicarte"}},["version"]="5.16.5",["welcome"]="Voyez d’un coup d’œil quand vous cherchez des partenaires de quête."},["itIT"]={["sections"]={{["illustration"]="quest-partners",["items"]={"Il tuo pulsante di QuestTogether sulla minimappa ora pulsa con lo stesso bagliore dorato del logo delle targhette dei nomi dei personaggi mentre Cerchi compagni per le missioni è attivo.","Il bagliore segue il tuo stato di compagno e si interrompe quando QT è disabilitato o il pulsante della minimappa è nascosto. Il tuo pulsante e il logo mantengono le dimensioni esistenti."},["title"]="Un promemoria luminoso sulla minimappa"}},["version"]="5.16.5",["welcome"]="Vedi a colpo d'occhio quando stai cercando compagni per le missioni."},["koKR"]={["sections"]={{["illustration"]="quest-partners",["items"]={"퀘스트 파트너 찾기가 켜져 있는 동안, QuestTogether 미니맵 버튼이 플레이어 이름표와 같은 금색 로고 빛으로 깜박입니다.","이 빛은 파트너 상태를 따라가며, QT가 비활성화되거나 미니맵 버튼이 숨겨지면 멈춥니다. 버튼과 로고는 기존 크기를 유지합니다."},["title"]="반짝이는 미니맵 알림"}},["version"]="5.16.5",["welcome"]="퀘스트를 함께할 파트너를 찾는 중인지 한눈에 확인하세요."},["ptBR"]={["sections"]={{["illustration"]="quest-partners",["items"]={"Seu botão do QuestTogether no minimapa agora pulsa com o mesmo brilho dourado do logotipo das placas de nome dos jogadores enquanto Procurando Parceiros para Missões está ativado.","O brilho acompanha seu status de parceiro e para quando o QT é desativado ou quando o botão do minimapa está oculto. Seu botão e logotipo mantêm o tamanho atual."},["title"]="Um lembrete brilhante no minimapa"}},["version"]="5.16.5",["welcome"]="Veja rapidamente quando você está procurando parceiros para fazer missões."},["ruRU"]={["sections"]={{["illustration"]="quest-partners",["items"]={"Кнопка QuestTogether у мини-карты теперь пульсирует тем же золотым свечением логотипа, что и индикаторы игроков, пока включен поиск напарников для заданий.","Свечение зависит от вашего статуса напарника и прекращается, когда QT отключен или кнопка у мини-карты скрыта. Ваша кнопка и логотип сохраняют текущий размер."},["title"]="Светящееся напоминание у мини-карты"}},["version"]="5.16.5",["welcome"]="Сразу видно, что вы ищете напарников для выполнения заданий."},["zhCN"]={["sections"]={{["illustration"]="quest-partners",["items"]={"当“寻找任务伙伴”开启时，你的 QuestTogether 小地图按钮现在会像玩家姓名板一样带有金色标志光晕并脉动。","该光晕会跟随你的伙伴状态，并在 QT 被禁用或小地图按钮隐藏时停止。你的按钮和标志会保持现有大小。"},["title"]="发光的小地图提醒"}},["version"]="5.16.5",["welcome"]="一目了然地查看你何时正在寻找任务伙伴。"},["zhTW"]={["sections"]={{["illustration"]="quest-partners",["items"]={"當「尋找任務夥伴」開啟時，你的 QuestTogether 小地圖按鈕現在會和玩家名條一樣，以金色標誌光芒閃動。","光芒會跟隨你的夥伴狀態，並在 QT 停用或小地圖按鈕隱藏時停止。你的按鈕和標誌會維持現有大小。"},["title"]="發光的小地圖提醒"}},["version"]="5.16.5",["welcome"]="一眼就能看出你正在尋找任務夥伴。"}}
